#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# ──────────────────────────────────────────────────────────────────────────
# STAGES: the Linux controller from docs/adr/0003: labd and lab-builder
# (Docker) on this Mac, the M1 enrolled as a Lab-owned Mac.
# ──────────────────────────────────────────────────────────────────────────
TOTAL_STAGES=8

REPO=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
BIN="$HOME/.local/bin"
DATA="$HOME/.local/share/maclab"
TAILNET_IP=$(tailscale ip -4 2>/dev/null | head -n1 || true)
DEVICE="${DEVICE:-m1}"
M1_HOST="${M1_HOST:-m1-air-omarchy}"
GO=(go)
go version >/dev/null 2>&1 || GO=(mise x go@1.27.1 -- go)   # a mise shim with no version set fails here

banner "maclab controller on Linux"

stage "Build the lab's binaries"
say "labd, lab and lab-builder for this Mac, lab-agent for the M1, into $BIN."
step "Repo: $REPO (branch: $(git -C "$REPO" branch --show-current))"
pause "Press Enter to build"
mkdir -p "$BIN"
(
  cd "$REPO"
  for c in labd lab lab-builder lab-agent; do
    CGO_ENABLED=0 "${GO[@]}" build -ldflags '-s -w' -o "$BIN/$c" "./cmd/$c"
  done
  # labd hands out the lab-agent beside its own binary, under this name.
  cp "$BIN/lab-agent" "$BIN/lab-agent-linux-arm64"
)
note "built: $(cd "$BIN" && ls labd lab lab-builder lab-agent | tr '\n' ' ')"
pause

stage "Docker"
say "lab-builder runs kernel builds in Docker. It runs as root (a system service), so"
say "nobody needs to join the docker group."
step "sudo systemctl enable --now docker"
sudo systemctl enable --now docker
sudo docker info --format 'docker {{.ServerVersion}}, {{.NCPU}} cpus, {{.MemTotal}} bytes' || warn "docker isn't answering"
pause

stage "The kbuild image and its cache"
say "The same image and cache volume the macOS builder uses (builder/Containerfile)."
note "The first image build downloads a Debian toolchain and Rust: several minutes."
pause "Press Enter to build the image"
sudo docker build -f "$REPO/builder/Containerfile" -t maclab-kbuild:1 "$REPO/builder/"
sudo docker volume inspect maclab-cache >/dev/null 2>&1 || sudo docker volume create maclab-cache
pause

stage "labd"
if [[ -z "$TAILNET_IP" ]]; then
  warn "No tailnet IPv4 address: is tailscale up?"
  ask TAILNET_IP "labd's listen address (this Mac's tailnet IP):"
fi
say "labd runs as your user service and listens on $TAILNET_IP:7770, over plain HTTP on the"
say "tailnet: WireGuard encrypts it. Desktop notifications say when a Mac needs hands."
mkdir -p "$HOME/.config/systemd/user"
cat > "$HOME/.config/systemd/user/labd.service" <<UNIT
[Unit]
Description=maclab controller
After=network-online.target

[Service]
ExecStart=$BIN/labd --listen $TAILNET_IP:7770 --allow-plain-http
Restart=always
RestartSec=3
Environment=MACLAB_NOTIFY_CMD=notify-send -u critical "\$MACLAB_TITLE" "\$MACLAB_BODY"

[Install]
WantedBy=default.target
UNIT
step "loginctl enable-linger: labd keeps running when you log out"
sudo loginctl enable-linger "$USER"
systemctl --user daemon-reload
systemctl --user enable --now labd
for _ in $(seq 20); do [[ -f "$DATA/builder.token" && -f "$DATA/admin.token" ]] && break; sleep 1; done
if "$BIN/lab" devices >/dev/null 2>&1; then
  note "lab is already logged in to labd."
elif [[ -f "$DATA/admin.token" ]]; then
  "$BIN/lab" login --allow-plain-http "http://$TAILNET_IP:7770" "$(cat "$DATA/admin.token")"
  "$BIN/lab" devices || true
else
  warn "labd made no tokens in $DATA. Look at: journalctl --user -u labd"
  SKIPPED+=("lab login --allow-plain-http http://$TAILNET_IP:7770 \"\$(cat $DATA/admin.token)\"")
fi
pause

stage "lab-builder"
say "Kernel builds with --runtime docker (malik-na/maclab#49), kernels only for now: package"
say "builds under Docker are untried. It runs as root and reads labd's builder.token from a"
say "copy only root can read."
sudo install -d -m 700 /etc/maclab /var/lib/maclab-builder
sudo install -m 600 "$DATA/builder.token" /etc/maclab/builder.token
sudo install -m 755 "$BIN/lab-builder" /usr/local/bin/lab-builder
sudo tee /etc/systemd/system/lab-builder.service >/dev/null <<UNIT
[Unit]
Description=maclab kernel builder (Docker)
After=docker.service network-online.target
Requires=docker.service

[Service]
ExecStart=/usr/local/bin/lab-builder --runtime docker --server http://$TAILNET_IP:7770 --allow-plain-http --token-file /etc/maclab/builder.token --io /var/lib/maclab-builder/io --cpus 12 --memory 32G --pkg-image ''
Restart=always
RestartSec=10

[Install]
WantedBy=multi-user.target
UNIT
sudo systemctl daemon-reload
sudo systemctl enable --now lab-builder
sleep 3
sudo journalctl -u lab-builder -n 5 --no-pager || true
note "A private GitHub repo needs a token in /root/.config/maclab/github-token."
pause

stage "Stay awake with the lid closed on power"
say "If this laptop suspends, labd stops mid-job. On AC power, closing the lid will do nothing."
note "On battery it still suspends, so plug in before a lab night."
if confirm "Write /etc/systemd/logind.conf.d/90-maclab-controller.conf"; then
  sudo install -d /etc/systemd/logind.conf.d
  printf '[Login]\nHandleLidSwitchExternalPower=ignore\nHandleLidSwitchDocked=ignore\n' |
    sudo tee /etc/systemd/logind.conf.d/90-maclab-controller.conf >/dev/null
  sudo systemctl kill -s HUP systemd-logind
  note "Undo: sudo rm /etc/systemd/logind.conf.d/90-maclab-controller.conf, then the same HUP."
else
  SKIPPED+=("lid switch on AC power: HandleLidSwitchExternalPower=ignore")
fi
pause

stage "Enroll the M1 as a Lab-owned Mac"
say "labd makes a one-time enrollment one-liner. Run it on the M1 as yourself: it asks"
say "for sudo, shows the lab's participation terms, and goes on only when you type yes."
"$BIN/lab" enroll "$DEVICE" --label "M1 Air, Naeem's desk"
step "Add --gui-user $USER --autologin to setup if the one-liner doesn't already: GUI tests need"
step "a logged-in desktop, and a Lab-owned Mac doesn't lock."
step "Open a shell on the M1 (ssh $USER@$M1_HOST over the tailnet, or at the M1) and paste it."
note "The one-liner holds the token: don't paste it anywhere else."
pause "Press Enter once setup on the M1 has finished"
"$BIN/lab" devices || true
pause

stage "Baseline and crash test"
say "The baseline reboots the M1 twice: once into the lab entry and once back, proving the"
say "one-shot boot selects and clears. No other job runs on it until this passes."
if confirm "Run lab baseline $DEVICE now (it reboots the M1)"; then
  "$BIN/lab" baseline "$DEVICE"
else
  SKIPPED+=("lab baseline $DEVICE")
fi
say "The crash test panics the M1 on purpose and checks it comes back by itself. With no"
say "out-of-band controller, a failure here means someone presses the power button."
if confirm "Run lab crashtest $DEVICE now"; then
  "$BIN/lab" crashtest "$DEVICE"
else
  SKIPPED+=("lab crashtest $DEVICE")
fi

finish
